export interface PortalResource {
  id: string;
  kind: "Course" | "Guide" | "Workshop";
  title: string;
  description: string;
  meta: string;
  saved?: boolean;
  href?: string;
}
export interface PortalSpotlight {
  title: string;
  description: string;
  completed: number;
  total: number;
  chapter: string;
  href?: string;
}
export interface PortalEvent {
  id: string;
  dateTime: string;
  dateLabel: string;
  timeLabel: string;
  title: string;
  detail: string;
  href?: string;
}
export interface PortalActivity {
  id: string;
  title: string;
  detail: string;
}
export interface PortalMetric {
  label: string;
  value: string;
  detail: string;
}
export interface Portal01Props {
  organization?: string;
  memberName?: string;
  memberRole?: string;
  title?: string;
  description?: string;
  resources?: readonly PortalResource[];
  spotlight?: PortalSpotlight | null;
  events?: readonly PortalEvent[];
  activity?: readonly PortalActivity[];
  metrics?: readonly PortalMetric[];
  notice?: string;
}
export const sampleResources: readonly PortalResource[] = [
  {
    id: "systems",
    kind: "Course",
    title: "Design systems, from first principles.",
    description: "Build a shared language for the things you make.",
    meta: "12 lessons / self-paced",
    saved: true,
  },
  {
    id: "research",
    kind: "Guide",
    title: "Ask better questions.",
    description: "A practical field guide to useful customer conversations.",
    meta: "18 min read",
    saved: true,
  },
  {
    id: "prototype",
    kind: "Workshop",
    title: "Make the idea tangible.",
    description: "Turn a promising direction into something you can test.",
    meta: "60 min / recorded session",
  },
  {
    id: "launch",
    kind: "Course",
    title: "From first draft to first launch.",
    description:
      "Find the smallest useful version, then put it into the world.",
    meta: "8 lessons / self-paced",
  },
];
export const sampleSpotlight: PortalSpotlight = {
  title: "Build a system that grows with you.",
  description:
    "Your next chapter brings the foundations together. Make room for the details that matter.",
  completed: 7,
  total: 12,
  chapter: "07 / Components that belong together",
};
export const sampleEvents: readonly PortalEvent[] = [
  {
    id: "crit",
    dateTime: "2027-01-11T14:00:00Z",
    dateLabel: "11 JAN",
    timeLabel: "14:00 UTC",
    title: "The open studio",
