  },
  {
    id: "office",
    dateTime: "2027-01-14T16:30:00Z",
    dateLabel: "14 JAN",
    timeLabel: "16:30 UTC",
    title: "Office hours",
    detail: "Bring one question. Leave with a next step.",
  },
];
export const sampleActivity: readonly PortalActivity[] = [
  {
    id: "lesson",
    title: "A foundation worth keeping",
    detail: "You completed a lesson / 2 hours ago",
  },
  {
    id: "guide",
    title: "Ask better questions",
    detail: "Added to your saved library / Yesterday",
  },
];
export const sampleMetrics: readonly PortalMetric[] = [
  {
    label: "Lessons completed",
    value: "12",
    detail: "A little further, every week.",
  },
  { label: "Your rhythm", value: "4 days", detail: "Keep a good thing going." },
  { label: "Current focus", value: "01", detail: "One path. Your own pace." },
];
export function filterPortalResources(
  resources: readonly PortalResource[],
  query: string,
  kind: string,
  saved: boolean,
) {
  const search = query.trim().toLocaleLowerCase("en-GB");
  return resources.filter(
    (item) =>
      (kind === "all" || item.kind === kind) &&
      (!saved || item.saved) &&
      `${item.title} ${item.description} ${item.kind}`
        .toLocaleLowerCase("en-GB")
        .includes(search),
  );
}
export function validatePortal(
  resources: readonly PortalResource[],
  spotlight?: PortalSpotlight | null,
  events: readonly PortalEvent[] = [],
  activity: readonly PortalActivity[] = [],
) {
  for (const list of [resources, events, activity]) {
    const ids = new Set<string>();
    for (const item of list) {
      if (!item.id.trim() || ids.has(item.id))
        throw new RangeError("Portal items require unique non-empty IDs.");
      ids.add(item.id);
    }
  }
  if (
    spotlight &&
    (!Number.isSafeInteger(spotlight.completed) ||
      !Number.isSafeInteger(spotlight.total) ||
      spotlight.total < 1 ||
      spotlight.completed < 0 ||
      spotlight.completed > spotlight.total)
  )
    throw new RangeError(
      "Portal progress requires a valid completed/total count.",
    );
}

.portal01 {
  --portal01-sidebar-width: calc(var(--space-4) * 13);
  --portal01-rail-width: 26%;
  --portal01-gap: var(--space-7);
  background: var(--background-secondary);
  color: var(--text-primary);
  font-family: var(--font-family-body);
}
.portal01 *,
.portal01 *::before,
.portal01 *::after {
  box-sizing: border-box;
}
.portal01 :is(h1, h2, h3, p, ol) {
  margin: 0;
}
.portal01 a {
  color: inherit;
  text-underline-offset: var(--space-1);
}
.portal01 a:focus-visible {
  outline: var(--focus-ring-width) solid var(--focus-ring-color);
  outline-offset: var(--focus-ring-offset);
}
.portal01 .portal01-shell {
  max-width: calc(var(--container-max-width) + var(--portal01-sidebar-width));
  margin-inline: auto;
  gap: 0;
  min-height: 100vh;
}
.portal01-sidebar {
  flex: 0 0 var(--portal01-sidebar-width);
  padding: var(--space-7) var(--space-5);
  background: var(--background-primary);
  border-inline-end: var(--border-width-thin) solid var(--border-default);
  display: flex;
  flex-direction: column;
  gap: var(--space-5);
}
.portal01-brand {
  display: flex;
  gap: var(--space-3);
  align-items: center;
  text-decoration: none;
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-semibold);
  margin-block-end: var(--space-7);
  overflow-wrap: anywhere;
}
.portal01-brand > span:first-child {
  background: var(--brand-primary);
  color: var(--text-on-brand);
  width: var(--space-9);
  aspect-ratio: 1;
  flex-shrink: 0;
  display: grid;
  place-items: center;
  border-radius: var(--form-radius);
  font-size: var(--font-size-xl);
}
.portal01-brand small {
  display: block;
  font-size: var(--typography-micro-size);
  letter-spacing: var(--letter-spacing-wide);
  font-weight: var(--font-weight-regular);
  color: var(--text-muted);
  margin-block-start: var(--space-1);
}
.portal01 .portal01-kicker {
  font-size: var(--typography-micro-size);
  font-weight: var(--font-weight-semibold);
  letter-spacing: var(--letter-spacing-wide);
  line-height: var(--line-height-relaxed);
  color: var(--text-muted);
}
.portal01-sidebar nav {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}
.portal01-sidebar nav a {
  display: flex;
  justify-content: space-between;
  gap: var(--space-3);
  padding: var(--space-3);
  text-decoration: none;
  border-radius: var(--form-radius);
  font-size: var(--typography-caption-size);
}
.portal01-sidebar nav a.is-active {
  background: var(--brand-primary-muted);
  color: var(--text-primary);
}
.portal01-sidebar nav a > span:last-child {
  font-variant-numeric: tabular-nums;
  color: var(--text-muted);
}
.portal01-sidebar-note {
  margin-block-start: auto;
  padding-block: var(--space-10) var(--space-5);
}
.portal01-sidebar-note p:last-child {
  margin-block-start: var(--space-3);
  font-size: var(--typography-caption-size);
  line-height: var(--line-height-relaxed);
}
.portal01 .portal01-member {
  border-block-start: var(--border-width-thin) solid var(--border-default);
  padding-block-start: var(--space-5);
}
.portal01-avatar {
  width: var(--space-9);
  aspect-ratio: 1;
  border-radius: var(--radius-full);
  background: var(--surface-base);
  display: grid;
  place-items: center;
  font-size: var(--typography-caption-size);
  flex-shrink: 0;
}
.portal01-member strong,
.portal01-member small {
  display: block;
  font-size: var(--typography-caption-size);
}
.portal01-member small {
  color: var(--text-muted);
  margin-block-start: var(--space-1);
}
.portal01-main {
  flex: 1 1 0;
  min-width: 0;
  padding: var(--space-7) var(--space-8);
}
.portal01 .portal01-topline {
  font-size: var(--typography-micro-size);
  letter-spacing: var(--letter-spacing-wide);
  padding-block-end: var(--space-5);
  border-block-end: var(--border-width-thin) solid var(--border-default);
  gap: var(--space-3);
}
.portal01 .portal01-intro {
  padding-block: var(--space-8);
  gap: var(--space-5);
}
.portal01-intro > div {
  flex: 1 1 65%;
}
.portal01-intro h1 {
  font-size: var(--website-title-size);
  line-height: var(--line-height-tight);
  letter-spacing: var(--letter-spacing-tighter);
  margin-block: var(--space-3);
}
.portal01-intro > div > p:last-child {
  font-size: var(--font-size-sm);
  line-height: var(--line-height-relaxed);
}
.portal01-intro > a {
  white-space: normal;
}
.portal01 .portal01-columns {
  gap: var(--portal01-gap);
}
.portal01-content {
  flex: 1 1 0;
  min-width: 0;
}
.portal01-feature {
  background: var(--brand-primary-muted);
  border: var(--border-width-thin) solid var(--border-default);
  border-radius: var(--card-radius);
  overflow: hidden;
}
.portal01-feature > .flex {
  gap: 0;
}
.portal01-feature-copy {
  flex: 1 1 65%;
  min-width: 0;
  padding: var(--space-6);
}
.portal01-feature-copy h2 {
  font-size: var(--font-size-2xl);
  line-height: var(--line-height-tight);
  letter-spacing: var(--letter-spacing-tight);
  margin-block: var(--space-3);
}
.portal01-feature-copy > p:not(.portal01-kicker) {
  font-size: var(--font-size-sm);
  line-height: var(--line-height-relaxed);
}
.portal01 .portal01-progress {
  margin-block: var(--space-6) var(--space-3);
}
.portal01-progress > .flex {
  font-size: var(--typography-caption-size);
  margin-block-end: var(--space-3);
  flex-wrap: wrap;
}
.portal01-chapter {
  font-size: var(--typography-caption-size);
}
.portal01-feature-copy > a {
  margin-block-start: var(--space-4);
}
.portal01-poster {
  flex: 0 0 32%;
  min-width: 0;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: var(--space-5);
  background: var(--brand-primary);
  color: var(--text-on-brand);
}
.portal01-poster span {
  font-size: var(--typography-micro-size);
  letter-spacing: var(--letter-spacing-wide);
  line-height: var(--line-height-relaxed);
}
.portal01-poster strong {
  font-size: calc(var(--font-size-4xl) * 2);
  line-height: var(--line-height-tight);
  letter-spacing: var(--letter-spacing-tighter);
  font-weight: var(--font-weight-semibold);
  margin-block: var(--space-6);
}
.portal01 .portal01-metrics {
  margin-block: var(--space-6) var(--space-9);
  gap: 0;
  border: var(--border-width-thin) solid var(--border-default);
  border-radius: var(--card-radius);
  background: var(--background-primary);
}
.portal01-metrics > div {
  flex: 1 1 30%;
  min-width: 0;
  padding: var(--space-5);
}
.portal01-metrics > div + div {
  border-inline-start: var(--border-width-thin) solid var(--border-default);
}
.portal01-metrics strong {
  display: block;
  font-size: var(--font-size-2xl);
  letter-spacing: var(--letter-spacing-tight);
  margin-block: var(--space-3);
}
.portal01-metrics > div > p:last-child {
  font-size: var(--typography-micro-size);
  color: var(--text-muted);
  line-height: var(--line-height-relaxed);
}
.portal01 .portal01-section-head {
  gap: var(--space-4);
  margin-block-end: var(--space-5);
}
.portal01-section-head h2 {
  font-size: var(--font-size-2xl);
  letter-spacing: var(--letter-spacing-tight);
  margin-block-start: var(--space-2);
}
.portal01-section-head > span {
  font-size: var(--typography-caption-size);
  color: var(--text-muted);
}
.portal01 .portal01-tools {
  gap: var(--space-3);
  margin-block-end: var(--space-5);
}
.portal01-search {
  flex: 1 1 40%;
  min-width: 0;
}
.portal01-tools .select {
  width: auto;
  max-width: 100%;
}
.portal01 .portal01-resource-grid {
  gap: var(--space-4);
}
.portal01 .portal01-resource {
  padding: 0;
  overflow: hidden;
  flex: 1 1 calc(50% - var(--space-4));
  min-width: 0;
  display: flex;
  flex-direction: column;
}
.portal01-art {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: var(--space-3);
  padding: var(--space-5);
  min-height: calc(var(--space-4) * 7);
  background: var(--brand-primary-muted);
  border-bottom: var(--border-width-thin) solid var(--border-default);
}
.portal01-art span {
  font-size: var(--typography-micro-size);
  letter-spacing: var(--letter-spacing-wide);
}
.portal01-art strong {
  font-size: var(--font-size-4xl);
  line-height: var(--line-height-tight);
  font-weight: var(--font-weight-regular);
}
.portal01-art[data-kind="Guide"] {
  background: var(--surface-base);
}
.portal01-art[data-kind="Workshop"] {
  background: var(--brand-primary);
  color: var(--text-on-brand);
}
.portal01-resource-copy {
  padding: var(--space-5);
  display: flex;
  flex-direction: column;
  flex: 1;
  gap: var(--space-3);
}
.portal01-resource-copy > .flex:first-child {
  font-size: var(--typography-caption-size);
}
.portal01-resource h3 {
  font-size: var(--font-size-lg);
  line-height: var(--line-height-snug);
  letter-spacing: var(--letter-spacing-tight);
}
.portal01-resource h3 a {
  text-decoration: none;
}
.portal01-resource h3 a:hover {
  text-decoration: underline;
}
.portal01-resource-copy > p {
  font-size: var(--font-size-sm);
  line-height: var(--line-height-relaxed);
}
.portal01 .portal01-resource-footer {
  margin-block-start: auto;
  padding-block-start: var(--space-4);
  font-size: var(--typography-micro-size);
  border-block-start: var(--border-width-thin) solid var(--border-default);
}
.portal01-rail {
  flex: 0 0 var(--portal01-rail-width);
  min-width: 0;
}
.portal01-rail section {
  padding-block: var(--space-5);
  border-block-start: var(--border-width-thin) solid var(--border-default);
}
.portal01-rail h2 {
  font-size: var(--font-size-lg);
  letter-spacing: var(--letter-spacing-tight);
  margin-block: var(--space-2) var(--space-5);
}
.portal01-rail ol {
  list-style: none;
  padding: 0;
}
.portal01-rail li + li {
  margin-block-start: var(--space-5);
  padding-block-start: var(--space-5);
  border-block-start: var(--border-width-thin) solid var(--border-default);
}
.portal01-date {
  flex: 0 0 calc(var(--space-4) * 3);
  padding: var(--space-3) var(--space-2);
  text-align: center;
  background: var(--surface-base);
  border-radius: var(--form-radius);
  font-size: var(--typography-caption-size);
  font-weight: var(--font-weight-semibold);
}
.portal01-rail h3 {
  font-size: var(--font-size-sm);
  line-height: var(--line-height-snug);
  margin-block: var(--space-2);
}
.portal01-rail p:not(.portal01-kicker),
.portal01-activity strong {
  font-size: var(--typography-caption-size);
  line-height: var(--line-height-relaxed);
}
.portal01-activity li {
  padding-inline-start: var(--space-4);
  border-inline-start: var(--border-width-thin) solid var(--brand-primary);
}
.portal01-activity p {
  margin-block-start: var(--space-2);
}
.portal01-rail-note {
  margin-block-start: var(--space-4);
  padding: var(--space-5);
  background: var(--surface-base);
  border-radius: var(--card-radius);
}
.portal01-rail-note > span {
  font-size: var(--font-size-2xl);
}
.portal01-rail-note h3 {
  margin-block: var(--space-5) var(--space-3);
}
.portal01-notice {
  margin-block-start: var(--space-8);
  padding-block-start: var(--space-4);
  border-block-start: var(--border-width-thin) solid var(--border-default);
  font-size: var(--typography-caption-size);
  color: var(--text-muted);
  line-height: var(--line-height-relaxed);
}
.portal01 :is(h1, h2, h3, p, strong, a) {
  overflow-wrap: anywhere;
}
@media (max-width: 1200px) {
  .portal01 {
    --portal01-rail-width: 100%;
  }
  .portal01 .portal01-columns {
    flex-wrap: wrap;
  }
  .portal01-content {
    flex-basis: 100%;
  }
  .portal01-rail {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-5);
  }
  .portal01-rail > section {
    flex: 1 1 40%;
  }
  .portal01-rail-note {
    flex-basis: 100%;
  }
}
@media (max-width: 800px) {
  .portal01 .portal01-shell {
    flex-direction: column;
  }
  .portal01-sidebar {
    flex-basis: auto;
    border-inline-end: 0;
    border-block-end: var(--border-width-thin) solid var(--border-default);
    padding: var(--space-4);
  }
  .portal01-brand {
    margin-block-end: 0;
  }
  .portal01-sidebar > .portal01-kicker,
  .portal01-sidebar-note,
  .portal01-member {
    display: none;
  }
  .portal01-sidebar nav {
    flex-direction: row;
    flex-wrap: wrap;
  }
  .portal01-sidebar nav a {
    flex: 1 1 40%;
  }
  .portal01-main {
    padding: var(--space-5) var(--space-4);
  }
}
@media (max-width: 500px) {
  .portal01-poster {
    display: none;
  }
  .portal01-feature-copy {
    padding: var(--space-5);
  }
  .portal01 .portal01-resource {
    flex-basis: 100%;
  }
  .portal01-metrics > div {
    flex-basis: 100%;
  }
  .portal01-metrics > div + div {
    border-inline-start: 0;
    border-block-start: var(--border-width-thin) solid var(--border-default);
  }
  .portal01-rail > section {
    flex-basis: 100%;
  }
  .portal01-search {
    flex-basis: 100%;
  }
}
